"if __name__ == '__main__':
    import sys
    n = int(sys.argv[1])
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    print(a)
"
int main(int argc, char **argv) {
    int n = atoi(argv[1]);
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) { long long t = b; b = a + b; a = t; }
    printf("%lld\n", a);
    return 0;
}
